import { defineConfig } from 'vite';

import react from '@vitejs/plugin-react';
import path from 'path';
import fs from 'fs';

// ===== SSL certificates (generated by mkcert) =====
// Run from root: mkcert 192.168.8.181 localhost 127.0.0.1
const certPath = path.resolve(__dirname, '../../192.168.8.181+2.pem');
const keyPath  = path.resolve(__dirname, '../../192.168.8.181+2-key.pem');
const hasSSL   = fs.existsSync(certPath) && fs.existsSync(keyPath);

export default defineConfig({
  server: {
    host: '0.0.0.0',
    port: 5173,
    ...(hasSSL && {
      https: {
        cert: fs.readFileSync(certPath),
        key:  fs.readFileSync(keyPath),
      },
    }),
  },
  plugins: [react()],
  resolve: {
    alias: {
      '@': path.resolve(__dirname, './src'),
    },
  },
});
